<script setup lang="ts">
import type { TableColumn } from "@nuxt/ui";
import type { AdminDeviceRecord, AdminMonitoringSummary } from "~/composables/useAdminMonitoring";

definePageMeta({ layout: "admin", middleware: ["admin"], title: "Devices" });
const api = useAdminMonitoring(); const auth = useAuth(); const toast = useToast();
const records = ref<AdminDeviceRecord[]>([]); const summary = ref<AdminMonitoringSummary | null>(null);
const loading = ref(false); const page = ref(1); const pageSize = 25; const total = ref(0);
const search = ref(""); const trust = ref("All"); const blocked = ref("All"); const deviceType = ref("All"); const profileType = ref("All");
const selected = ref<AdminDeviceRecord | null>(null); const detailOpen = ref(false); const actionOpen = ref(false);
const action = ref<"trust" | "untrust" | "block" | "unblock" | "revoke-sessions">("trust"); const reason = ref(""); const acting = ref(false);
const trustItems = ["All", "Trusted", "Untrusted"]; const blockedItems = ["All", "Blocked", "Allowed"];
const deviceItems = ["All", "Desktop", "Laptop", "Tablet", "Mobile Phone", "Unknown Device"]; const profileItems = ["All", "Student", "Faculty", "Librarian", "Administrator"];
const columns: TableColumn<AdminDeviceRecord>[] = [
  { id: "device", header: "Device" }, { id: "account", header: "Account" }, { id: "trust", header: "Security State" },
  { id: "seen", header: "Last Seen" }, { id: "sessions", header: "Portal Sessions" }, { id: "actions", header: "" },
];
function formatDate(value: string | null) { if (!value) return "Not recorded"; return new Intl.DateTimeFormat("en-PH", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Manila" }).format(new Date(value)); }
async function loadSummary() { try { summary.value = await api.summary(); } catch (error) { console.warn(error); } }
async function load() { loading.value = true; try { const response = await api.devices({ page: page.value, pageSize, search: search.value, trust: trust.value, blocked: blocked.value, deviceType: deviceType.value, profileType: profileType.value }); records.value = response.data; total.value = response.meta.total; } catch (error) { toast.add({ title: "Unable to load devices", description: auth.getErrorMessage(error), color: "error", icon: "i-lucide-circle-alert" }); } finally { loading.value = false; } }
function view(record: AdminDeviceRecord) { selected.value = record; detailOpen.value = true; }
function begin(record: AdminDeviceRecord, next: typeof action.value) { selected.value = record; action.value = next; reason.value = ""; detailOpen.value = false; actionOpen.value = true; }
const actionLabel = computed(() => ({ trust: "Mark as Trusted", untrust: "Remove Trusted Status", block: "Block Device", unblock: "Unblock Device", "revoke-sessions": "Revoke Device Sessions" })[action.value]);
async function confirm() { if (!selected.value || reason.value.trim().length < 5) return; acting.value = true; try { const response = await api.deviceAction(selected.value, action.value, reason.value.trim()); const description = action.value === "block" ? "This device is now denied from signing in, refreshing its session, and accessing protected portal data." : response.data.revokedAuthenticationSessions ? `${response.data.authenticationRevocationScope} were revoked for safety.` : selected.value.displayName; toast.add({ title: actionLabel.value, description, color: "success", icon: "i-lucide-circle-check" }); actionOpen.value = false; await load(); await loadSummary(); } catch (error) { toast.add({ title: "Unable to update device", description: auth.getErrorMessage(error), color: "error", icon: "i-lucide-circle-alert" }); } finally { acting.value = false; } }
let timer: ReturnType<typeof setTimeout> | undefined;
watch([trust, blocked, deviceType, profileType], () => { page.value = 1; load(); }); watch(page, load); watch(search, () => { clearTimeout(timer); timer = setTimeout(() => { page.value = 1; load(); }, 350); });
onMounted(() => { load(); loadSummary(); });
</script>

<template>
  <div class="sncbt-page-shell space-y-6">
    <AdminPageHeader eyebrow="System & Monitoring" title="Devices" description="Review privacy-safe browser device records created by Student, Faculty, Librarian, and Administrator portal sessions." icon="i-lucide-monitor-smartphone"><template #actions><div class="flex flex-wrap gap-2"><UButton label="Reports" icon="i-lucide-file-chart-column" color="neutral" variant="outline" to="/admin/reports?view=monitoring" /><UButton label="Refresh" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="loading" @click="load(); loadSummary()" /></div></template></AdminPageHeader>
    <UAlert color="primary" variant="soft" icon="i-lucide-fingerprint" title="No hardware fingerprinting" description="The Library System uses a random application device identifier. It does not collect MAC addresses, IMEI numbers, hardware serial numbers, continuous location, or personal files." />
    <div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <AdminMetricCard label="Known Devices" :value="summary?.knownDevices ?? 0" description="Registered privacy-safe devices." icon="i-lucide-monitor-smartphone" tone="primary" :loading="!summary" />
      <AdminMetricCard label="New This Week" :value="summary?.newDevicesSevenDays ?? 0" description="First observed in the last seven days." icon="i-lucide-sparkles" tone="info" :loading="!summary" />
      <AdminMetricCard label="Blocked Devices" :value="summary?.blockedDevices ?? 0" description="Denied from login, refresh, and protected portal access." icon="i-lucide-ban" tone="error" :loading="!summary" />
      <AdminMetricCard label="Active Portal Sessions" :value="summary?.activeTrackedSessions ?? 0" description="Recently active portal monitoring sessions." icon="i-lucide-monitor-dot" tone="success" :loading="!summary" to="/admin/sessions" />
    </div>
    <UCard :ui="{ body: 'p-0 sm:p-0' }">
      <template #header><div class="space-y-3"><div class="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><h2 class="font-semibold text-highlighted">Device Register</h2><p class="mt-1 text-xs text-muted">{{ total }} matching device{{ total === 1 ? '' : 's' }}</p></div><UInput v-model="search" icon="i-lucide-search" placeholder="Search device, user, browser, or OS" class="w-full lg:max-w-sm" /></div><div class="grid gap-2 sm:grid-cols-2 xl:grid-cols-4"><USelect v-model="trust" :items="trustItems" /><USelect v-model="blocked" :items="blockedItems" /><USelect v-model="deviceType" :items="deviceItems" /><USelect v-model="profileType" :items="profileItems" /></div></div></template>
      <div v-if="loading" class="space-y-3 p-6"><USkeleton v-for="i in 7" :key="i" class="h-16 w-full" /></div>
      <div v-else-if="!records.length" class="px-6 py-16 text-center"><UIcon name="i-lucide-monitor-off" class="mx-auto size-11 text-dimmed" /><h3 class="mt-3 font-semibold text-highlighted">No matching devices</h3><p class="mt-1 text-sm text-muted">Devices appear after a supported user opens their portal.</p></div>
      <UTable v-else :data="records" :columns="columns">
        <template #device-cell="{ row }"><div class="flex items-center gap-3"><div class="flex size-10 items-center justify-center rounded-xl bg-elevated"><UIcon :name="row.original.deviceType === 'Mobile Phone' ? 'i-lucide-smartphone' : 'i-lucide-monitor'" class="size-5" /></div><div><p class="font-semibold text-highlighted">{{ row.original.displayName }}</p><p class="text-xs text-muted">{{ row.original.deviceType }} · {{ row.original.applicationMode }}</p></div></div></template>
        <template #account-cell="{ row }"><UButton :label="row.original.account.username" :to="`/admin/users/${row.original.account.id}/devices`" color="neutral" variant="link" class="h-auto p-0 font-medium" /><p class="text-xs text-muted">{{ row.original.profileType }} · {{ row.original.account.email || 'No email' }}</p></template>
        <template #trust-cell="{ row }"><div class="flex flex-wrap gap-1"><UBadge v-if="row.original.blocked" label="Blocked" color="error" variant="soft" /><UBadge v-else label="Allowed" color="success" variant="soft" /><UBadge :label="row.original.trusted ? 'Trusted' : 'Untrusted'" :color="row.original.trusted ? 'primary' : 'neutral'" variant="soft" /></div></template>
        <template #seen-cell="{ row }"><p class="text-sm text-default">{{ formatDate(row.original.lastSeenAt) }}</p><p class="text-xs text-muted">First: {{ formatDate(row.original.firstSeenAt) }}</p></template>
        <template #sessions-cell="{ row }"><UBadge :label="`${row.original.activeSessionCount} active`" :color="row.original.activeSessionCount ? 'success' : 'neutral'" variant="soft" /></template>
        <template #actions-cell="{ row }"><UButton icon="i-lucide-eye" color="neutral" variant="ghost" square aria-label="View device" @click="view(row.original)" /></template>
      </UTable>
      <template #footer><div class="flex justify-end"><UPagination v-model:page="page" :total="total" :items-per-page="pageSize" /></div></template>
    </UCard>
  </div>

  <UModal v-model:open="detailOpen" :ui="{ content: 'sm:max-w-2xl' }"><template #content><div v-if="selected" class="space-y-5 bg-default p-6"><div class="flex items-start justify-between"><div><h2 class="text-xl font-bold text-highlighted">{{ selected.displayName }}</h2><p class="mt-1 text-sm text-muted">{{ selected.account.username }} · {{ selected.profileType }}</p></div><UBadge :label="selected.blocked ? 'Blocked' : 'Allowed'" :color="selected.blocked ? 'error' : 'success'" variant="soft" /></div><dl class="grid gap-4 text-sm sm:grid-cols-2"><div><dt class="text-xs font-semibold uppercase text-muted">Device Type</dt><dd class="mt-1 text-highlighted">{{ selected.deviceType }}</dd></div><div><dt class="text-xs font-semibold uppercase text-muted">Application</dt><dd class="mt-1 text-highlighted">{{ selected.applicationMode }}</dd></div><div><dt class="text-xs font-semibold uppercase text-muted">Browser</dt><dd class="mt-1 text-highlighted">{{ selected.browser }} {{ selected.browserVersion || '' }}</dd></div><div><dt class="text-xs font-semibold uppercase text-muted">Operating System</dt><dd class="mt-1 text-highlighted">{{ selected.operatingSystem }}</dd></div><div><dt class="text-xs font-semibold uppercase text-muted">First Seen</dt><dd class="mt-1 text-highlighted">{{ formatDate(selected.firstSeenAt) }}</dd></div><div><dt class="text-xs font-semibold uppercase text-muted">Last Seen</dt><dd class="mt-1 text-highlighted">{{ formatDate(selected.lastSeenAt) }}</dd></div><div><dt class="text-xs font-semibold uppercase text-muted">Masked Network</dt><dd class="mt-1 font-mono text-xs text-highlighted">{{ selected.maskedIpAddress || 'Not recorded' }}</dd></div><div><dt class="text-xs font-semibold uppercase text-muted">Portal Sessions</dt><dd class="mt-1 text-highlighted">{{ selected.activeSessionCount }} active</dd></div></dl><div class="flex flex-wrap justify-end gap-2"><UButton label="Close" color="neutral" variant="outline" @click="() => { detailOpen = false; }" /><UButton :label="selected.trusted ? 'Remove Trust' : 'Mark Trusted'" :icon="selected.trusted ? 'i-lucide-shield-off' : 'i-lucide-shield-check'" color="primary" variant="soft" @click="begin(selected, selected.trusted ? 'untrust' : 'trust')" /><UButton label="Revoke Sessions" icon="i-lucide-log-out" color="warning" variant="soft" @click="begin(selected, 'revoke-sessions')" /><UButton :label="selected.blocked ? 'Unblock Device' : 'Block Device'" :icon="selected.blocked ? 'i-lucide-shield-check' : 'i-lucide-ban'" :color="selected.blocked ? 'success' : 'error'" @click="begin(selected, selected.blocked ? 'unblock' : 'block')" /></div></div></template></UModal>
  <UModal v-model:open="actionOpen" :ui="{ content: 'sm:max-w-lg' }"><template #content><div class="space-y-5 bg-default p-6"><div><h2 class="text-xl font-bold text-highlighted">{{ actionLabel }}</h2><p class="mt-2 text-sm text-muted">Apply this security action to {{ selected?.displayName }} used by {{ selected?.account.username }}.</p></div><UFormField label="Administrative reason" required><UTextarea v-model="reason" :rows="4" placeholder="Explain why this device action is required" /></UFormField><UAlert v-if="action === 'block'" color="error" variant="soft" icon="i-lucide-shield-ban" title="Device access will be denied" description="This device will no longer be allowed to use the account. Other devices for the same account remain available." /><UAlert v-else-if="action === 'revoke-sessions'" color="warning" variant="soft" icon="i-lucide-triangle-alert" title="Authentication sessions" description="For safety, revoking sessions from this device may sign the account out from other active sessions as well." /><div class="flex justify-end gap-2"><UButton label="Cancel" color="neutral" variant="outline" @click="() => { actionOpen = false; }" /><UButton :label="actionLabel" :color="action === 'block' ? 'error' : 'primary'" :loading="acting" :disabled="reason.trim().length < 5" @click="confirm" /></div></div></template></UModal>
</template>
